function reviewPoHistory(rows){
  const groups=new Map();
  for(const row of rows)for(const event of row.history||[]){
    if(event.result!=='SAVED'||!event.commercialChanged||!event.commercialBefore||!event.commercialAfter)continue;
    const key=event.requestId||event.id;if(!groups.has(key))groups.set(key,{time:event.time,amendment:event.amendment,lines:new Map()});
    groups.get(key).lines.set(row.id,{row,event});
  }
  const money=s=>Number.isSafeInteger(s?.amountCents)?'MYR '+num(s.amountCents/100):'Not recorded 未记录';
  const cbm=s=>Number.isFinite(s?.quantity)&&Number.isFinite(s?.cbmPerCtn)?(s.quantity*s.cbmPerCtn).toFixed(3):'Not recorded 未记录';
  const basis=s=>{const c=s?.costing;if(!c)return 'Unit price 单价';return c.mode+(c.mode==='FOC'?' · Paid '+c.paidCtn+' + FOC '+c.freeCtn:'')+(c.moneySource==='TOTAL'?' · Total amount 总额':'');};
  return '<details class="po-review-changes"><summary>Revision history 修改记录 · '+[...groups.values()].filter(g=>g.amendment).length+'</summary>'+([...groups.values()].sort((a,b)=>String(b.time).localeCompare(String(a.time))).map(g=>'<section><b>'+esc(shortTime(g.time))+' · '+(g.amendment?'Amended 已修改':'Original PO 原采购单')+'</b><table><thead><tr><th>Item</th><th>Qty CTN</th><th>Line Amount</th><th>Line CBM</th><th>Cost basis</th></tr></thead><tbody>'+[...g.lines.values()].map(({row,event:e})=>'<tr><td>'+esc(row.barcode)+'<small>'+esc(row.name)+'</small></td><td>'+esc(e.commercialBefore.quantity??'—')+' → '+esc(e.commercialAfter.quantity??'—')+'</td><td>'+esc(money(e.commercialBefore))+' → '+esc(money(e.commercialAfter))+'</td><td>'+esc(cbm(e.commercialBefore))+' → '+esc(cbm(e.commercialAfter))+'</td><td>'+esc(basis(e.commercialBefore))+' → '+esc(basis(e.commercialAfter))+'</td></tr>').join('')+'</tbody></table></section>').join('')||'<p>No recorded revisions 尚无修订记录。Older changes without snapshots are not reconstructed 历史缺失资料不作推算。</p>')+'</details>';
}
